import json

def save_checkpoint(path, state):
    with open(path, "w") as f:      # atomic write in real use: tmp + rename
        json.dump(state, f)

def load_checkpoint(path):
    try:
        with open(path) as f:
            return json.load(f)
    except FileNotFoundError:
        return {"step": 0, "summary": "", "plan": []}

state = load_checkpoint("agent_state.json")
# ... run steps, updating state["summary"] and state["plan"] ...
save_checkpoint("agent_state.json", state)  # pause/resume + audit trail

