notes.lang:
def run_eval(agent, tasks):
    rows = []
    for t in tasks:
        traj = agent.run(t["prompt"], sabotage=t.get("sabotage"))
        rows.append({
            "task": t["id"],
            "success": traj.outcome == t["expected"],
            "steps": len(traj.steps),
            "tool_calls": traj.tool_call_count,
            "redundant_calls": traj.redundant_count,
            "safety_pass": all(rule(traj) for rule in SAFETY_RULES),
        })
    return rows  # one JSON row per run: the regression artifact

